import{z as n,x as m,o as e,c as s,q as A,j as l,D as t,d as r,s as o,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"信任域与单调改进","description":"","frontmatter":{"title":"信任域与单调改进","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/trust-region-monotone.md","filePath":"llm/trust-region-monotone.md","lastUpdated":1791413859000}'),d={name:"llm/trust-region-monotone.md"};function p(h,a,D,L,C,F){const i=m("Mermaid");return e(),s("div",null,[a[2]||(a[2]=A('<h1 id="信任域与单调改进" tabindex="-1">信任域与单调改进 <a class="header-anchor" href="#信任域与单调改进" aria-label="Permalink to &quot;信任域与单调改进&quot;">​</a></h1><div class="epigraph"><p>监督学习里步子迈错，损失函数还在原地等你回头；策略学习里步子迈错，下一批数据由坏策略生成，连退路都一起拆了。</p><footer>—— 据 Kakade &amp; Langford, 2002；Schulman et al., TRPO, ICML 2015 整理</footer></div><p><a href="/llm/actor-critic-bootstrap">上一课</a>用自举把每步信用结清，但没回答另一个问题：每次更新该走多远。一阶方法把 \\(\\theta\\) 推太远时，采样分布整个挪走，优势估计失准，性能崖式下跌——上一单元的网格世界实验课里，tabular 小步长都能震荡，函数逼近下更甚。本课写信任域思想：Kakade–Langford 的单调改进界如何把「别走太远」变成可证的保证，TRPO 如何把这个界折成带 KL 约束的一阶目标加二阶度量，以及为什么实现里从不显式构出那个二阶矩阵。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>策略学习的步长陷阱有三层。其一，梯度是旧分布下估的：泰勒近似只在采样点附近有效，走远了 \\(\\mathbb{E}_{\\tau\\sim\\pi_\\theta}\\) 的支撑都变了，梯度方向不再指向上坡。其二，参数步长与分布步长脱节：\\(\\theta\\) 移动很小，某些动作的概率可能从 0.5 被推到 0.001——监督学习的损失面是固定的，这里的「面」本身随策略重建。其三，不可恢复：坏策略采不到好区域的数据，探索随之塌缩，没有外部数据集兜底。REINFORCE 到 actor-critic 的所有一阶更新都暴露在这三层下，调好步长靠运气。</p><p><span class="marginnote">可以把信任域想成手电筒下的地图：泰勒近似这张「局部地图」只在光圈范围内可信。梯度告诉你光圈中心最陡的方向，但光圈外的地形它一概不知——走出去之后，方向再漂亮也是猜的。信任域的全部内容就是：每步只允许在光圈以内走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Kakade–Langford 2002 的保守策略迭代（CPI）给出第一块可证地基：新策略取混合 \\(\\pi_{\\mathrm{new}}=(1-\\alpha)\\pi+\\alpha\\pi&#39;\\) 时，</p> \\[J(\\pi_{\\mathrm{new}})\\ \\ge\\ J(\\pi)-C\\,\\max_s D_{\\mathrm{TV}}\\bigl(\\pi(\\cdot\\mid s),\\pi_{\\mathrm{new}}(\\cdot\\mid s)\\bigr), \\]<p>惩罚系数 \\(C\\) 只由折扣 \\(\\gamma\\) 与优势上界 \\(\\epsilon\\) 决定，\\(\\gamma\\to 1\\)（长地平线）时爆炸。读法：<strong>只要策略改动足够小，性能下界就是可计算的</strong>——单调改进不是祝福，是拿改动幅度换来的保证。TRPO 把它工程化：惩罚换成硬约束、总变差换成 KL（Pinsker 不等式保证 KL 控制 TV），目标用重要性比率写成</p> \\[\\max_\\theta\\ \\mathbb{E}\\bigl[\\tfrac{\\pi_\\theta(a\\mid s)}{\\pi_{\\mathrm{old}}(a\\mid s)}\\hat A(s,a)\\bigr]\\quad \\mathrm{s.t.}\\quad \\mathbb{E}\\bigl[\\mathrm{KL}\\bigl(\\pi_{\\mathrm{old}}(\\cdot\\mid s)\\,\\Vert\\,\\pi_\\theta(\\cdot\\mid s)\\bigr)\\bigr]\\le\\delta, \\]<p>再对目标与约束同时做二阶泰勒展开，解出 \\(\\theta\\propto F^{-1}g\\)（\\(F\\) 是 Fisher 矩阵，\\(g\\) 是梯度）：参数空间里按分布空间度量走的最陡方向，即自然梯度。</p>',12)),(e(),l(B,null,{default:t(()=>[o(i,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20OLD%5B%22%E6%97%A7%E7%AD%96%E7%95%A5%E9%87%87%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20ADV%5B%22%E4%BC%B0%E8%AE%A1%E4%BC%98%E5%8A%BF%22%5D%0A%20%20ADV%20--%3E%20SUR%5B%22KL%20%E7%90%83%E5%86%85%E6%9C%80%E5%A4%A7%E5%8C%96%E4%BB%A3%E7%90%86%E7%9B%AE%E6%A0%87%22%5D%0A%20%20SUR%20--%3E%20CG%5B%22%E5%85%B1%E8%BD%AD%E6%A2%AF%E5%BA%A6%E8%A7%A3%20Fisher%20%E6%96%B9%E7%A8%8B%22%5D%0A%20%20CG%20--%3E%20LS%5B%22%E5%9B%9E%E6%BA%AF%E7%BA%BF%E6%90%9C%E7%B4%A2%EF%BC%9AKL%20%E8%BE%BE%E6%A0%87%E4%B8%94%E4%BB%A3%E7%90%86%E6%94%B9%E5%96%84%22%5D%0A%20%20LS%20--%3E%20NEW%5B%22%E6%96%B0%E7%AD%96%E7%95%A5%22%5D%0A%20%20NEW%20--%3E%20OLD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"「不推全部二阶」的账：Fisher 矩阵是参数量的平方量级（LLM 下天文数字），从未显式构造。实现用共轭梯度解 \\(Fx=g\\)，每步只需矩阵-向量积 \\(Fv\\)——对 KL 做一次 Hessian-向量积，成本约等于一两次反向传播；随后线搜索逐半缩小步长，直到 KL 真的达标。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"KL 散度可以翻译成「把分布 \\(p\\) 错当成分布 \\(q\\) 用时，平均每步多付的代价」：两分布重合时为 0，差异越大越大，而且不对称，\\(\\mathrm{KL}(p\\Vert q)\\ne\\mathrm{KL}(q\\Vert p)\\)。所以约束 \\(\\mathrm{KL}(\\pi_{\\mathrm{old}}\\Vert\\pi_\\theta)\\le\\delta\\) 读作：新策略与旧策略的差距必须不超过预算 \\(\\delta\\)。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"约束为什么优于惩罚：\\(C\\) 含未知的优势上界与 \\(1/(1-\\gamma)\\) 因子，固定惩罚系数要么太弱（约束不住）要么压倒目标（不动）；硬约束把「区域多大」从学习率问题里剥离，\\(\\delta\\) 直接以分布距离计价，与参数化无关——这是 KL 度量的真正好处：两个参数化不同的策略，KL 相同就是分布上同样近。线搜索是单调性的最后防线：解析解只在局部有效，逐半退回直到代理目标真的改善且 KL 未超。这样得到的每步更新，「不变差」有近似保证——理论上不再依赖步长运气。",-1)),(e(),l(B,null,{default:t(()=>[o(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SL%5B%22%E7%9B%91%E7%9D%A3%E5%AD%A6%E4%B9%A0%EF%BC%9A%E6%8D%9F%E5%A4%B1%E9%9D%A2%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20SB%5B%22%E6%AD%A5%E5%AD%90%E8%BF%88%E9%94%99%22%5D%0A%20%20SB%20--%3E%20RECOV%5B%22%E8%AE%AD%E7%BB%83%E9%9B%86%E8%BF%98%E5%9C%A8%E5%8E%9F%E5%9C%B0%EF%BC%8C%E5%8F%AF%E4%BB%A5%E5%9B%9E%E5%A4%B4%E9%87%8D%E7%AE%97%22%5D%0A%20%20RL%5B%22%E7%AD%96%E7%95%A5%E5%AD%A6%E4%B9%A0%EF%BC%9A%E6%95%B0%E6%8D%AE%E7%94%B1%E5%BD%93%E5%89%8D%E7%AD%96%E7%95%A5%E7%94%9F%E6%88%90%22%5D%20--%3E%20SB2%5B%22%E6%AD%A5%E5%AD%90%E8%BF%88%E9%94%99%22%5D%0A%20%20SB2%20--%3E%20DRIFT%5B%22%E9%87%87%E6%A0%B7%E5%88%86%E5%B8%83%E6%95%B4%E4%B8%AA%E6%8C%AA%E8%B5%B0%EF%BC%8C%E4%BC%98%E5%8A%BF%E4%BC%B0%E8%AE%A1%E5%A4%B1%E5%87%86%22%5D%0A%20%20DRIFT%20--%3E%20COLLAPSE%5B%22%E5%9D%8F%E7%AD%96%E7%95%A5%E9%87%87%E4%B8%8D%E5%88%B0%E5%A5%BD%E6%95%B0%E6%8D%AE%EF%BC%8C%E6%8E%A2%E7%B4%A2%E5%A1%8C%E7%BC%A9%22%5D%0A%20%20COLLAPSE%20--%3E%20NEED%5B%22%E9%94%99%E8%AF%AF%E4%B8%8D%E5%8F%AF%E6%81%A2%E5%A4%8D%EF%BC%8C%E9%A1%BB%E7%94%A8%E4%BF%A1%E4%BB%BB%E5%9F%9F%E9%99%90%E6%AD%A5%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<p><span class="marginnote">初学者容易以为信任域是在参数空间里画球：参数挪动别超过某个半径。实际上球画在分布空间——参数移动一点点，某些动作的概率就可能从 0.5 跌到 0.001，采样分布已面目全非。以 KL 计价的好处正在于此：不管网络怎么参数化，「分布上近」的含义都一致，超参 \\(\\delta\\) 才有跨任务复用的可能。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>保证的成色要说清：单调界属于原始的 CPI 混合与精确优势；TRPO 做了三处近似（max 换期望、TV 换 KL、优势靠样本估计），实际更新只有「近似单调」，性能仍会小幅回退。\\(\\delta\\) 仍是超参，只是从「参数步长」换成「分布步长」，后者至少跨任务可迁移。二阶计算的每步开销换来大步稳定，样本效率高但墙钟慢；千亿参数、每条 rollout 上万 token 的 LLM 场景里，这份开销要重新算——把约束再降成一阶的裁剪，是下一课 PPO 的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失败模式：更新过远使采样分布挪移、梯度失准、探索塌缩且不可恢复。</li><li>CPI 单调改进界：策略改动（TV/KL）足够小，则性能下界可计算。</li><li>TRPO：KL 约束下的重要性比率最大化，自然梯度方向 \\(F^{-1}g\\)。</li><li>实现从不构造 Fisher 矩阵：共轭梯度加 Fisher-向量积，线搜索兜底。</li><li>三处近似使「单调」打折；二阶开销在 LLM 规模上催生一阶替代。</li><li>出处：Kakade &amp; Langford, <em>Approximately Optimal Approximate Reinforcement Learning</em>, ICML 2002；Schulman et al., <em>Trust Region Policy Optimization</em>, ICML 2015。</li></ul>',5))])}const _=n(d,[["render",p]]);export{u as __pageData,_ as default};
